/**
 * Pixi World Map - CPU generated terrain + Pixi viewport
 *
 * Renders the terrain generated by the pixiTerrainRenderer pipeline and connects
 * it to campaign systems: movement callbacks, encounter rolls, and settlement discovery.
 */

import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Application, Container, Graphics, Text, TextStyle } from 'pixi.js';
import { Viewport } from 'pixi-viewport';
import { WorldPos } from '../../../core/types';
import { initTerrainGenerator, sampleOverworld } from '../terrain/terrainGenerator';
import {
    generateTerrain,
    pickPixelScale,
    setSeedAndRegenerate,
    setDimetric,
    TerrainOptionsOverrides,
    TerrainOverlayDefinition
} from '../terrain/pixiTerrainRenderer';
import { SeededRandom } from '../../../proc/noise';

interface WorldLandmark {
    id: string;
    type: 'settlement' | 'encounter' | 'point';
    position: WorldPos;
    label?: string;
}

interface PixiWorldMapProps {
    seed: string;
    onEncounter?: (_pos: WorldPos) => void;
    onSettlement?: (_pos: WorldPos) => void;
    onPositionChange?: (_pos: WorldPos) => void;
    landmarks?: WorldLandmark[];
}

type Keys = Record<string, boolean>;

type TerrainApp = Application & {
    terrainLayer?: Container;
    overlayLayer?: Container;
    playerMarker?: Graphics;
};

const PLAYER_RADIUS = 10;
const ACCELERATION = 520;
const DRAG = 0.86;
const WORLD_UNIT_TO_PIXEL = 8;
const POSITION_EMIT_INTERVAL_MS = 400;
const ENCOUNTER_DISTANCE = 90; // world units
const SETTLEMENT_DISTANCE = 260;
const ENCOUNTER_COOLDOWN_MS = 5000;
const SETTLEMENT_COOLDOWN_MS = 12000;

const computeMapDimensions = (screenWidth: number, screenHeight: number) => {
    const minWidth = 1600;
    const minHeight = 900;
    const width = Math.max(minWidth, Math.ceil(screenWidth * 1.6));
    const height = Math.max(minHeight, Math.ceil(screenHeight * 1.6));
    return { width, height };
};

const attachTerrainLayers = (app: TerrainApp, viewport: Viewport) => {
    if (app.terrainLayer && app.terrainLayer.parent !== viewport) {
        app.terrainLayer.parent?.removeChild(app.terrainLayer);
        viewport.addChildAt(app.terrainLayer, 0);
    }
    if (app.overlayLayer && app.overlayLayer.parent !== viewport) {
        app.overlayLayer.parent?.removeChild(app.overlayLayer);
        viewport.addChild(app.overlayLayer);
    }
};

const clonePos = (pos: WorldPos): WorldPos => ({ x: pos.x, y: pos.y });

const settlementFriendlyBiomes = new Set(['plains', 'forest', 'hills', 'shore']);

const LANDMARK_STYLE: Record<WorldLandmark['type'], { fill: string; stroke: string }> = {
    settlement: { fill: '#ffcc66', stroke: '#3a2500' },
    encounter: { fill: '#ff6666', stroke: '#3a0000' },
    point: { fill: '#66b3ff', stroke: '#102b4c' }
};

export default function PixiWorldMap({
    seed,
    onEncounter,
    onSettlement,
    onPositionChange,
    landmarks = []
}: PixiWorldMapProps) {
    const containerRef = useRef<HTMLDivElement | null>(null);
    const appRef = useRef<TerrainApp | null>(null);
    const viewportRef = useRef<Viewport | null>(null);
    const wheelHandlerRef = useRef<((_e: WheelEvent) => void) | null>(null);

    const posRef = useRef<WorldPos>({ x: 0, y: 0 });
    const prevPosRef = useRef<WorldPos>({ x: 0, y: 0 });
    const velRef = useRef({ x: 0, y: 0 });
    const keysRef = useRef<Keys>({});
    const terrainReadyRef = useRef(false);

    const mapPixelSizeRef = useRef<{ width: number; height: number }>({ width: 0, height: 0 });
    const mapWorldSizeRef = useRef<{ width: number; height: number }>({ width: 0, height: 0 });
    const pixelScaleRef = useRef(1);

    const lastEmitTimeRef = useRef<number>(0);
    const lastEmitPosRef = useRef<WorldPos>({ x: 0, y: 0 });

    const travelRef = useRef<{ encounter: number; settlement: number }>({ encounter: 0, settlement: 0 });
    const lastEventTimeRef = useRef<{ encounter: number; settlement: number }>({
        encounter: 0,
        settlement: 0
    });

    const [fps, setFps] = useState(60);
    const fpsSamplesRef = useRef<number[]>([]);
    const lastFrameRef = useRef<number>(performance.now());

    // Dimetric camera controls
    const dimetricRef = useRef({ scaleY: 0.5, shearX: 0.5 });
    const [dimetricDisplay, setDimetricDisplay] = useState({ scaleY: 0.5, shearX: 0.5 });
    const rightDragRef = useRef({ active: false, startX: 0, startY: 0, startScaleY: 0.5, startShearX: 0.5 });
    const dimetricHandlersRef = useRef<{
        mousedown: ((_e: MouseEvent) => void) | null;
        mousemove: ((_e: MouseEvent) => void) | null;
        mouseup: ((_e: MouseEvent) => void) | null;
        contextmenu: ((_e: MouseEvent) => void) | null;
    }>({ mousedown: null, mousemove: null, mouseup: null, contextmenu: null });

    const landmarkOverlays = useMemo<TerrainOverlayDefinition[]>(() => {
        if (!landmarks || landmarks.length === 0) {
            return [];
        }

        const hash = landmarks
            .map(l => `${l.id}:${l.type}:${l.position.x.toFixed(2)}:${l.position.y.toFixed(2)}:${l.label ?? ''}`)
            .join('|');

        return [
            {
                id: 'landmarks',
                hash,
                zIndex: 10,
                opacity: 0.95,
                paint: (ctx, context) => {
                    ctx.clearRect(0, 0, context.width, context.height);
                    const fontSize = Math.max(10, Math.round(10 * context.pixelScale));
                    ctx.font = `${fontSize}px monospace`;
                    ctx.textBaseline = 'middle';

                    for (const landmark of landmarks) {
                        const px = landmark.position.x * WORLD_UNIT_TO_PIXEL;
                        const py = landmark.position.y * WORLD_UNIT_TO_PIXEL;

                        const style = LANDMARK_STYLE[landmark.type] ?? LANDMARK_STYLE.point;
                        const size = Math.max(6, Math.round(8 * context.pixelScale));

                        ctx.fillStyle = style.fill;
                        ctx.strokeStyle = style.stroke;
                        ctx.lineWidth = Math.max(1, context.pixelScale);

                        if (landmark.type === 'settlement') {
                            ctx.beginPath();
                            ctx.rect(px - size / 2, py - size / 2, size, size);
                            ctx.fill();
                            ctx.stroke();
                        } else {
                            ctx.beginPath();
                            ctx.arc(px, py, size / 2, 0, Math.PI * 2);
                            ctx.fill();
                            ctx.stroke();
                        }

                        if (landmark.label) {
                            ctx.fillStyle = '#ffffff';
                            ctx.strokeStyle = 'rgba(0,0,0,0.6)';
                            ctx.lineWidth = Math.max(2, context.pixelScale * 1.5);
                            ctx.strokeText(landmark.label, px + size, py);
                            ctx.fillText(landmark.label, px + size, py);
                        }
                    }
                }
            }
        ];
    }, [landmarks]);

    useEffect(() => {
        let cancelled = false;
        const timer = window.setTimeout(() => {
            if (cancelled) return;
            try {
                initTerrainGenerator(seed);
            } catch (error) {
                console.error('[PixiWorldMap] Failed to initialise terrain generator', error);
            }
        }, 60);

        travelRef.current = { encounter: 0, settlement: 0 };
        lastEventTimeRef.current = { encounter: 0, settlement: 0 };

        return () => {
            cancelled = true;
            window.clearTimeout(timer);
        };
    }, [seed]);

    useEffect(() => {
        const container = containerRef.current;
        if (!container) return;

        const screenWidth = container.clientWidth || 1280;
        const screenHeight = container.clientHeight || 720;
        const mapSize = computeMapDimensions(screenWidth, screenHeight);

        mapPixelSizeRef.current = mapSize;
        mapWorldSizeRef.current = {
            width: mapSize.width / WORLD_UNIT_TO_PIXEL,
            height: mapSize.height / WORLD_UNIT_TO_PIXEL
        };
        pixelScaleRef.current = pickPixelScale(mapSize.width, mapSize.height);

        const centerPos: WorldPos = {
            x: mapWorldSizeRef.current.width / 2,
            y: mapWorldSizeRef.current.height / 2
        };
        posRef.current = clonePos(centerPos);
        prevPosRef.current = clonePos(centerPos);
        lastEmitPosRef.current = clonePos(centerPos);

        const app = new Application() as TerrainApp;

        (async () => {
            await app.init({
                width: screenWidth,
                height: screenHeight,
                backgroundColor: 0x1a1a2e,
                resolution: window.devicePixelRatio || 1,
                autoDensity: true,
                antialias: false,
                powerPreference: 'high-performance'
            });

            container.appendChild(app.canvas as HTMLCanvasElement);
            appRef.current = app;

            // Prevent page scrolling on mouse wheel over canvas
            const canvas = app.canvas as HTMLCanvasElement;
            const preventScroll = (e: WheelEvent) => {
                e.preventDefault();
            };
            wheelHandlerRef.current = preventScroll;
            canvas.addEventListener('wheel', preventScroll, { passive: false });

            const viewport = new Viewport({
                screenWidth,
                screenHeight,
                worldWidth: mapSize.width,
                worldHeight: mapSize.height,
                events: app.renderer.events
            });

            app.stage.addChild(viewport as any);
            viewportRef.current = viewport;

            viewport
                .drag({ mouseButtons: 'left' })
                .pinch()
                .wheel({ smooth: 3, percent: 0.1 })
                .decelerate({ friction: 0.9 })
                .clamp({
                    left: 0,
                    right: mapSize.width,
                    top: 0,
                    bottom: mapSize.height
                })
                .clampZoom({
                    minScale: 0.5,
                    maxScale: 8
                });

            viewport.setZoom(1, true);

            const initialOverrides: TerrainOptionsOverrides = {
                seed,
                width: mapSize.width,
                height: mapSize.height,
                overlays: landmarkOverlays
            };
            generateTerrain(app, initialOverrides);
            attachTerrainLayers(app, viewport);
            terrainReadyRef.current = true;

            // Right-click drag to adjust dimetric view angle
            const handleMouseDown = (e: MouseEvent) => {
                if (e.button === 2) { // Right click
                    e.preventDefault();
                    rightDragRef.current = {
                        active: true,
                        startX: e.clientX,
                        startY: e.clientY,
                        startScaleY: dimetricRef.current.scaleY,
                        startShearX: dimetricRef.current.shearX
                    };
                    canvas.style.cursor = 'grab';
                }
            };

            const handleMouseMove = (e: MouseEvent) => {
                if (!rightDragRef.current.active) return;

                const drag = rightDragRef.current;
                const deltaX = e.clientX - drag.startX;
                const deltaY = e.clientY - drag.startY;

                // Horizontal drag adjusts shearX (rotation)
                // Vertical drag adjusts scaleY (viewing angle steepness)
                const newShearX = Math.max(0.0, Math.min(0.8, drag.startShearX + deltaX * 0.002));
                const newScaleY = Math.max(0.3, Math.min(1.0, drag.startScaleY - deltaY * 0.002));

                dimetricRef.current = { scaleY: newScaleY, shearX: newShearX };
                setDimetric(app, dimetricRef.current);
                setDimetricDisplay({ scaleY: newScaleY, shearX: newShearX });
            };

            const handleMouseUp = (e: MouseEvent) => {
                if (e.button === 2 && rightDragRef.current.active) {
                    rightDragRef.current.active = false;
                    canvas.style.cursor = '';
                }
            };

            const handleContextMenu = (e: MouseEvent) => {
                e.preventDefault(); // Prevent default context menu
            };

            // Store handlers for cleanup
            dimetricHandlersRef.current = {
                mousedown: handleMouseDown,
                mousemove: handleMouseMove,
                mouseup: handleMouseUp,
                contextmenu: handleContextMenu
            };

            canvas.addEventListener('mousedown', handleMouseDown);
            canvas.addEventListener('mousemove', handleMouseMove);
            canvas.addEventListener('mouseup', handleMouseUp);
            canvas.addEventListener('contextmenu', handleContextMenu);

            const player = new Graphics();
            player.circle(0, 0, PLAYER_RADIUS);
            player.fill(0xff2244);
            player.stroke({ width: 2, color: 0xffffff });
            viewport.addChild(player);
            app.playerMarker = player;

            const spawnPixelX = centerPos.x * WORLD_UNIT_TO_PIXEL;
            const spawnPixelY = centerPos.y * WORLD_UNIT_TO_PIXEL;
            player.position.set(spawnPixelX, spawnPixelY);
            viewport.moveCenter(spawnPixelX, spawnPixelY);

            const fpsStyle = new TextStyle({
                fontFamily: 'monospace',
                fontSize: 14,
                fill: 0x00ff00
            });
            const fpsText = new Text({ text: 'FPS: 60', style: fpsStyle });
            fpsText.position.set(10, 10);
            app.stage.addChild(fpsText);

            app.ticker.add(() => {
                const now = performance.now();
                const dt = Math.min(0.05, (now - lastFrameRef.current) / 1000);
                lastFrameRef.current = now;

                const samples = fpsSamplesRef.current;
                const currentFps = dt > 0 ? 1 / dt : 60;
                samples.push(currentFps);
                if (samples.length > 30) samples.shift();
                const avgFps = samples.reduce((a, b) => a + b, 0) / samples.length;
                const roundedFps = Math.round(avgFps);
                setFps(roundedFps);
                fpsText.text = `FPS: ${roundedFps}`;
                fpsText.style.fill = roundedFps >= 55 ? 0x00ff00 : roundedFps >= 30 ? 0xffff00 : 0xff0000;

                const keys = keysRef.current;
                let inputX = 0;
                let inputY = 0;

                if (keys['KeyW'] || keys['ArrowUp']) inputY -= 1;
                if (keys['KeyS'] || keys['ArrowDown']) inputY += 1;
                if (keys['KeyA'] || keys['ArrowLeft']) inputX -= 1;
                if (keys['KeyD'] || keys['ArrowRight']) inputX += 1;

                if (inputX !== 0 && inputY !== 0) {
                    inputX *= 0.707;
                    inputY *= 0.707;
                }

                velRef.current.x += inputX * ACCELERATION * dt;
                velRef.current.y += inputY * ACCELERATION * dt;

                velRef.current.x *= DRAG;
                velRef.current.y *= DRAG;

                const previousPos = clonePos(posRef.current);

                posRef.current.x += velRef.current.x * dt;
                posRef.current.y += velRef.current.y * dt;

                const maxWorldX = mapWorldSizeRef.current.width;
                const maxWorldY = mapWorldSizeRef.current.height;
                posRef.current.x = Math.max(0, Math.min(maxWorldX, posRef.current.x));
                posRef.current.y = Math.max(0, Math.min(maxWorldY, posRef.current.y));

                const pixelX = posRef.current.x * WORLD_UNIT_TO_PIXEL;
                const pixelY = posRef.current.y * WORLD_UNIT_TO_PIXEL;
                player.position.set(pixelX, pixelY);
                viewport.moveCenter(pixelX, pixelY);

                const dx = posRef.current.x - prevPosRef.current.x;
                const dy = posRef.current.y - prevPosRef.current.y;
                const distanceMoved = Math.hypot(dx, dy);
                prevPosRef.current = clonePos(posRef.current);

                travelRef.current.encounter += distanceMoved;
                travelRef.current.settlement += distanceMoved;

                if (onPositionChange) {
                    const emitDistance = Math.hypot(
                        posRef.current.x - lastEmitPosRef.current.x,
                        posRef.current.y - lastEmitPosRef.current.y
                    );
                    if (
                        emitDistance > 0.5 ||
                        now - lastEmitTimeRef.current > POSITION_EMIT_INTERVAL_MS
                    ) {
                        onPositionChange(clonePos(posRef.current));
                        lastEmitPosRef.current = clonePos(posRef.current);
                        lastEmitTimeRef.current = now;
                    }
                }

                const sampleTerrain = () => {
                    try {
                        return sampleOverworld(posRef.current);
                    } catch (err) {
                        console.warn('[PixiWorldMap] Terrain sample failed', err);
                        return null;
                    }
                };

                if (
                    onEncounter &&
                    travelRef.current.encounter >= ENCOUNTER_DISTANCE &&
                    now - lastEventTimeRef.current.encounter >= ENCOUNTER_COOLDOWN_MS
                ) {
                    const sample = sampleTerrain();
                    if (sample && sample.biome !== 'water' && !sample.blocked) {
                        const rng = new SeededRandom(
                            `${seed}:encounter:${Math.round(posRef.current.x)}:${Math.round(posRef.current.y)}:${Math.floor(now / 60000)}`
                        );
                        const biomeModifier =
                            sample.biome === 'mountains'
                                ? 0.45
                                : sample.biome === 'forest'
                                    ? 0.35
                                    : sample.biome === 'swamp'
                                        ? 0.3
                                        : 0.22;
                        if (rng.next() < biomeModifier) {
                            onEncounter(clonePos(posRef.current));
                            lastEventTimeRef.current.encounter = now;
                            travelRef.current.encounter = 0;
                        } else {
                            travelRef.current.encounter = 0;
                        }
                    } else {
                        travelRef.current.encounter = ENCOUNTER_DISTANCE * 0.5;
                    }
                }

                if (
                    onSettlement &&
                    travelRef.current.settlement >= SETTLEMENT_DISTANCE &&
                    now - lastEventTimeRef.current.settlement >= SETTLEMENT_COOLDOWN_MS
                ) {
                    const sample = sampleTerrain();
                    if (sample && settlementFriendlyBiomes.has(sample.biome)) {
                        const rng = new SeededRandom(
                            `${seed}:settlement:${Math.round(posRef.current.x)}:${Math.round(posRef.current.y)}:${Math.floor(now / 90000)}`
                        );
                        const baseChance = sample.biome === 'plains' ? 0.18 : 0.12;
                        if (rng.next() < baseChance) {
                            onSettlement(clonePos(posRef.current));
                            lastEventTimeRef.current.settlement = now;
                            travelRef.current.settlement = 0;
                        } else {
                            travelRef.current.settlement = SETTLEMENT_DISTANCE * 0.4;
                        }
                    } else {
                        travelRef.current.settlement = SETTLEMENT_DISTANCE * 0.3;
                    }
                }

                if (distanceMoved <= 0.0001 && Math.hypot(velRef.current.x, velRef.current.y) > 0.01) {
                    posRef.current = clonePos(previousPos);
                    velRef.current = { x: 0, y: 0 };
                }
            });
        })();

        const onKeyDown = (event: KeyboardEvent) => {
            keysRef.current[event.code] = true;
        };
        const onKeyUp = (event: KeyboardEvent) => {
            keysRef.current[event.code] = false;
        };

        window.addEventListener('keydown', onKeyDown);
        window.addEventListener('keyup', onKeyUp);

        const onResize = () => {
            if (!containerRef.current || !appRef.current || !viewportRef.current) return;
            const w = containerRef.current.clientWidth || 1280;
            const h = containerRef.current.clientHeight || 720;
            appRef.current.renderer.resize(w, h);
            viewportRef.current.resize(
                w,
                h,
                mapPixelSizeRef.current.width,
                mapPixelSizeRef.current.height
            );
        };
        window.addEventListener('resize', onResize);

        return () => {
            window.removeEventListener('keydown', onKeyDown);
            window.removeEventListener('keyup', onKeyUp);
            window.removeEventListener('resize', onResize);

            // Remove wheel event listener from canvas
            if (appRef.current?.canvas && wheelHandlerRef.current) {
                const canvas = appRef.current.canvas as HTMLCanvasElement;
                canvas.removeEventListener('wheel', wheelHandlerRef.current);
            }

            // Remove dimetric control event listeners
            if (appRef.current?.canvas) {
                const canvas = appRef.current.canvas as HTMLCanvasElement;
                const handlers = dimetricHandlersRef.current;
                if (handlers.mousedown) canvas.removeEventListener('mousedown', handlers.mousedown);
                if (handlers.mousemove) canvas.removeEventListener('mousemove', handlers.mousemove);
                if (handlers.mouseup) canvas.removeEventListener('mouseup', handlers.mouseup);
                if (handlers.contextmenu) canvas.removeEventListener('contextmenu', handlers.contextmenu);
            }

            if (appRef.current) {
                appRef.current.destroy(true, { children: true });
            }
            appRef.current = null;
            viewportRef.current = null;
            terrainReadyRef.current = false;
            fpsSamplesRef.current = [];
            travelRef.current = { encounter: 0, settlement: 0 };
            lastEventTimeRef.current = { encounter: 0, settlement: 0 };
        };
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    useEffect(() => {
        if (!appRef.current || !viewportRef.current || !terrainReadyRef.current) return;

        generateTerrain(appRef.current, {
            width: mapPixelSizeRef.current.width,
            height: mapPixelSizeRef.current.height,
            overlays: landmarkOverlays
        });
        attachTerrainLayers(appRef.current, viewportRef.current);
    }, [landmarkOverlays]);

    useEffect(() => {
        if (!appRef.current || !viewportRef.current || !terrainReadyRef.current) return;

        const overrides: TerrainOptionsOverrides = {
            width: mapPixelSizeRef.current.width,
            height: mapPixelSizeRef.current.height,
            overlays: landmarkOverlays,
            forceRegenerate: true
        };

        setSeedAndRegenerate(appRef.current, seed, overrides);
        attachTerrainLayers(appRef.current, viewportRef.current);

        const centerPos: WorldPos = {
            x: mapWorldSizeRef.current.width / 2,
            y: mapWorldSizeRef.current.height / 2
        };
        posRef.current = clonePos(centerPos);
        prevPosRef.current = clonePos(centerPos);
        lastEmitPosRef.current = clonePos(centerPos);

        const pixelX = centerPos.x * WORLD_UNIT_TO_PIXEL;
        const pixelY = centerPos.y * WORLD_UNIT_TO_PIXEL;
        if (appRef.current.playerMarker) {
            appRef.current.playerMarker.position.set(pixelX, pixelY);
        }
        viewportRef.current.moveCenter(pixelX, pixelY);

        travelRef.current = { encounter: 0, settlement: 0 };
        lastEventTimeRef.current = { encounter: 0, settlement: 0 };
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [seed]);

    return (
        <div style={{ width: '100%', height: '100%', position: 'relative' }}>
            <div
                ref={containerRef}
                style={{
                    width: '100%',
                    height: '100%',
                    overflow: 'hidden',
                    touchAction: 'none'
                }}
            />

            <div
                style={{
                    position: 'absolute',
                    bottom: 10,
                    left: 10,
                    background: 'rgba(0,0,0,0.7)',
                    color: 'white',
                    padding: '8px 12px',
                    borderRadius: 4,
                    fontFamily: 'monospace',
                    fontSize: 12,
                    pointerEvents: 'none'
                }}
            >
                <div>WASD: Move | Mouse: Drag/Zoom | Right-Click: Camera Angle</div>
                <div>
                    Pos (world): {posRef.current.x.toFixed(1)}, {posRef.current.y.toFixed(1)}
                </div>
                <div>
                    Map: {Math.round(mapWorldSizeRef.current.width)}x
                    {Math.round(mapWorldSizeRef.current.height)} wu | pixelScale~{pixelScaleRef.current}
                </div>
                <div>Seed: {seed}</div>
                <div>
                    Camera: scaleY={dimetricDisplay.scaleY.toFixed(2)} shearX={dimetricDisplay.shearX.toFixed(2)}
                </div>
                <div style={{ color: fps >= 55 ? '#0f0' : fps >= 30 ? '#ff0' : '#f00' }}>FPS: {fps}</div>
            </div>
        </div>
    );
}
